// This file is generated by AI.

// 差异色块的行装饰区间断言。
//
// 这里钉住一个踩过的坑: **区间必须覆盖整行**。曾经给的是折叠区间 `(line,1)-(line,1)`,
// Monaco 会把它换算到视觉行坐标的折出来的第一行, 于是开启自动换行后, 长行的色块
// 只有首行有颜色 —— 代码上完全看不出问题, 只有把区间摊成整行才覆盖所有折行。

import { describe, expect, it, vi } from 'vitest';

import { DIFF_GUTTER_CLASS, diffGutterMarks } from '../src/editor/diff-gutter';

/** 假文档: 第 n 行的 `getLineMaxColumn` 返回多少 */
const maxColumns = new Map([
  [1, 13],
  [2, 41],
  [3, 8],
]);

const lineMaxColumn = (line: number) => maxColumns.get(line) ?? 1;

describe('diffGutterMarks', () => {
  it('色块覆盖整行, 而不是只落在第一个视觉行上的折叠区间', () => {
    const marks = diffGutterMarks([{ line: 2, kind: 'M' }], 5, lineMaxColumn);
    expect(marks).toEqual([{ lineNumber: 2, endColumn: 41, className: 'diff-gutter-modified' }]);
  });

  it('按改动类型选色块', () => {
    const marks = diffGutterMarks(
      [
        { line: 1, kind: 'A' },
        { line: 2, kind: 'M' },
        { line: 3, kind: 'D' },
      ],
      5,
      lineMaxColumn
    );
    expect(marks.map((mark) => mark.className)).toEqual([
      DIFF_GUTTER_CLASS.A,
      DIFF_GUTTER_CLASS.M,
      DIFF_GUTTER_CLASS.D,
    ]);
  });

  it('行号超出文档 (文档比差异来源短) 时夹到最后一行', () => {
    const marks = diffGutterMarks([{ line: 99, kind: 'A' }], 3, lineMaxColumn);
    expect(marks[0]?.lineNumber).toBe(3);
  });

  it('行号小于 1 时夹到首行', () => {
    const marks = diffGutterMarks([{ line: 0, kind: 'A' }], 3, lineMaxColumn);
    expect(marks[0]?.lineNumber).toBe(1);
  });

  it('行数为 0 的文档也留一行可用', () => {
    const marks = diffGutterMarks([{ line: 5, kind: 'A' }], 0, lineMaxColumn);
    expect(marks[0]?.lineNumber).toBe(1);
  });

  it('行宽问的是夹住之后的行号', () => {
    const width = vi.fn(() => 9);
    diffGutterMarks([{ line: 99, kind: 'A' }], 3, width);
    expect(width).toHaveBeenCalledWith(3);
  });

  it('行宽异常时 endColumn 至少为 1', () => {
    const marks = diffGutterMarks([{ line: 1, kind: 'A' }], 3, () => 0);
    expect(marks[0]?.endColumn).toBe(1);
  });

  it('没有改动时不画任何色块', () => {
    expect(diffGutterMarks([], 3, lineMaxColumn)).toEqual([]);
  });
});
